candidate_y6_values = [
    # Placeholders (replace with true candidates):
    11566970769751918491610151872792277288283331820339291628907029137377693901869,
    10410712671013222760867540720223232799159231566579081360655210170044138899731,
]

encflag = b'\x84\x0bk\xfbmp\x1aV\x95q\r\x9bZ/s\xe5\xb4\xa5Y~y\xac\xaa\xd1\xff\xf1\xf1\xee#\xbd\x07:n\x9c\xd6\xcdV*\xfc\xbe0\x96\xff\xff\xa1E\xdd\xb3\x96\xa2\xb2\x8cW\xc2#6Y\xa0\xf2\xd7\xb7*\xbb\xfb'
encflag_int = int.from_bytes(encflag, 'big')

matches = []
for cand_y6 in candidate_y6_values:
    candidate_int = encflag_int ^ cand_y6
    # Attempt various paddings/lengths just in case
    for pad in range(3):
        clen = len(encflag) + pad
        candidate_bytes = candidate_int.to_bytes(clen, 'big')
        if candidate_bytes.startswith(b'flag{'):
            matches.append(candidate_bytes)
            print(f"Found Flag: {candidate_bytes.decode(errors='replace')}")
        else:
            try:
                decoded = candidate_bytes.decode()
                if 'flag{' in decoded:
                    matches.append(candidate_bytes)
                    print(f"Contains Flag: {decoded}")
            except Exception:
                continue
if not matches:
    print('No flag candidates found in given candidate_y6_values.')
